CREATE   PROCEDURE dbo.SP_Compra_Actualizar @IdCompra bigint,@IdProducto int,@IdProveedor int,@IdPresentacionProducto int,@FechaCompra date,@CantidadComprada decimal(18,4),@PrecioTotal decimal(18,4),@Moneda nvarchar(10),@Observaciones nvarchar(500)=NULL AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 DECLARE @TranInicial int=@@TRANCOUNT;
 IF @TranInicial=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION CompraReal;
 BEGIN TRY
 EXEC dbo.usp_Presupuesto_Bloquear;
 IF @CantidadComprada IS NULL OR @CantidadComprada<=0 OR @PrecioTotal IS NULL OR @PrecioTotal<=0 OR @FechaCompra IS NULL OR @FechaCompra>CONVERT(date,GETDATE())
 THROW 52000,N'Compra requiere fecha no futura y cantidad e importe positivos.',1;
 SET @Moneda=UPPER(LTRIM(RTRIM(@Moneda)));
 IF @Moneda IS NULL OR @Moneda NOT IN(N'CRC',N'USD') THROW 52000,N'El modulo historico de compras admite CRC o USD.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.Productos p JOIN dbo.ProductosBase b ON b.IdProductoBase=p.IdProductoBase LEFT JOIN dbo.Marcas m ON m.IdMarca=p.IdMarca
 JOIN dbo.PresentacionesProducto pp ON pp.IdProducto=p.IdProducto JOIN dbo.UnidadesMedida u ON u.IdUnidadMedida=pp.IdUnidadMedida
 WHERE p.IdProducto=@IdProducto AND pp.IdPresentacionProducto=@IdPresentacionProducto AND p.Activo=1 AND b.Activo=1 AND (p.IdMarca IS NULL OR m.Activo=1) AND pp.Activo=1 AND u.Activo=1)
 OR NOT EXISTS(SELECT 1 FROM dbo.Proveedores WHERE IdProveedor=@IdProveedor AND Activo=1) THROW 52000,N'Catalogos inactivos o producto y presentacion incompatibles.',1;
 DECLARE @Precio decimal(18,6)=TRY_CONVERT(decimal(18,6),@PrecioTotal/@CantidadComprada);
 IF @Precio IS NULL OR @Precio<=0 THROW 52000,N'Precio por empaque fuera de rango.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.Compras WITH(UPDLOCK,HOLDLOCK) WHERE IdCompra=@IdCompra) THROW 52004,N'Compra no existe.',1;
 IF EXISTS(SELECT 1 FROM dbo.vw_ComprasImputadasPresupuesto WHERE IdCompra=@IdCompra)
 AND EXISTS(SELECT 1 FROM dbo.Compras WHERE IdCompra=@IdCompra AND
 (IdProducto<>@IdProducto OR IdProveedor<>@IdProveedor OR IdPresentacionProducto<>@IdPresentacionProducto
 OR FechaCompra<>@FechaCompra OR CantidadComprada<>@CantidadComprada OR PrecioTotal<>@PrecioTotal OR Moneda<>@Moneda))
 THROW 52010,N'Revierta la imputación presupuestaria antes de cambiar los datos de la compra.',1;
 DECLARE @ProductoAnterior int,@PresentacionAnterior int,@MonedaAnterior nvarchar(10);
 DECLARE @Cabecera bigint=(SELECT IdCompraCabecera FROM dbo.Compras WHERE IdCompra=@IdCompra);
 IF @Cabecera IS NOT NULL
 BEGIN
   IF EXISTS(SELECT 1 FROM dbo.ComprasCabecera WHERE IdCompraCabecera=@Cabecera
     AND (IdProveedor<>@IdProveedor OR FechaCompra<>@FechaCompra OR Moneda<>@Moneda))
     AND (SELECT COUNT(*) FROM dbo.Compras WHERE IdCompraCabecera=@Cabecera)>1
     THROW 52010,N'Cambie proveedor, fecha y moneda desde la cabecera de la compra completa.',1;
   UPDATE dbo.ComprasCabecera SET IdProveedor=@IdProveedor,FechaCompra=@FechaCompra,Moneda=@Moneda,
     FechaModificacion=SYSUTCDATETIME() WHERE IdCompraCabecera=@Cabecera;
 END;
 SELECT @ProductoAnterior=IdProducto,@PresentacionAnterior=IdPresentacionProducto,@MonedaAnterior=Moneda FROM dbo.Compras WHERE IdCompra=@IdCompra;
 UPDATE dbo.Compras SET IdProducto=@IdProducto,IdProveedor=@IdProveedor,IdPresentacionProducto=@IdPresentacionProducto,FechaCompra=@FechaCompra,
 CantidadComprada=@CantidadComprada,PrecioTotal=@PrecioTotal,Moneda=@Moneda,PrecioUnitarioCalculado=@Precio,Observaciones=NULLIF(LTRIM(RTRIM(@Observaciones)),N''),FechaModificacion=SYSDATETIME() WHERE IdCompra=@IdCompra;
 /* Cache de compatibilidad; todas las lecturas usan la vista recalculada. */
 UPDATE c SET PrecioUnitarioCalculado=v.PrecioUnitarioCalculado,IdCompraAnterior=v.IdCompraAnterior,PrecioUnitarioAnterior=v.PrecioUnitarioAnterior,
 DiferenciaPrecio=v.DiferenciaPrecio,PorcentajeCambioPrecio=v.PorcentajeCambioPrecio,TendenciaPrecio=v.TendenciaPrecio
 FROM dbo.Compras c JOIN dbo.vw_ComprasAnalisis v ON v.IdCompra=c.IdCompra
 WHERE c.IdProducto=@IdProducto AND c.IdPresentacionProducto=@IdPresentacionProducto AND c.Moneda=@Moneda;
 UPDATE c SET IdCompraAnterior=v.IdCompraAnterior,PrecioUnitarioAnterior=v.PrecioUnitarioAnterior,DiferenciaPrecio=v.DiferenciaPrecio,PorcentajeCambioPrecio=v.PorcentajeCambioPrecio,TendenciaPrecio=v.TendenciaPrecio
 FROM dbo.Compras c JOIN dbo.vw_ComprasAnalisis v ON v.IdCompra=c.IdCompra
 WHERE c.IdProducto=@ProductoAnterior AND c.IdPresentacionProducto=@PresentacionAnterior AND c.Moneda=@MonedaAnterior;
 SELECT @IdCompra AS IdCompraActualizada;
 IF @TranInicial=0 COMMIT;
 END TRY BEGIN CATCH
 IF XACT_STATE()<>0 AND @TranInicial=0 ROLLBACK; ELSE IF XACT_STATE()=1 ROLLBACK TRANSACTION CompraReal;
 THROW;
 END CATCH;
END;

CREATE   PROCEDURE dbo.SP_Compra_HistorialPorProducto @IdProducto int,@Moneda nvarchar(10)=NULL AS
BEGIN
 SET NOCOUNT ON;
 SELECT * FROM dbo.vw_ComprasAnalisis WHERE IdProducto=@IdProducto AND (@Moneda IS NULL OR Moneda=@Moneda) ORDER BY FechaCompra DESC,IdCompra DESC;
END;

CREATE   PROCEDURE dbo.SP_Compra_Insertar @IdProducto int,@IdProveedor int,@IdPresentacionProducto int,@FechaCompra date,@CantidadComprada decimal(18,4),@PrecioTotal decimal(18,4),@Moneda nvarchar(10),@Observaciones nvarchar(500)=NULL,
 @DistribucionPresupuestoJson nvarchar(max)=NULL,@IdOperacionPresupuesto uniqueidentifier=NULL,
 @MotivoPresupuesto nvarchar(500)=NULL,@MotivoExcesoPresupuesto nvarchar(500)=NULL,
 @IdCompraCabecera bigint=NULL,@NumeroLinea int=NULL,@IdCompraInsertada bigint=NULL OUTPUT,@DevolverResultado bit=1 AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 DECLARE @TranInicial int=@@TRANCOUNT;
 IF @TranInicial=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION CompraReal;
 BEGIN TRY
 EXEC dbo.usp_Presupuesto_Bloquear;
 IF @CantidadComprada IS NULL OR @CantidadComprada<=0 OR @PrecioTotal IS NULL OR @PrecioTotal<=0 OR @FechaCompra IS NULL OR @FechaCompra>CONVERT(date,GETDATE())
 THROW 52000,N'Compra requiere fecha no futura y cantidad e importe positivos.',1;
 SET @Moneda=UPPER(LTRIM(RTRIM(@Moneda)));
 IF @Moneda IS NULL OR @Moneda NOT IN(N'CRC',N'USD') THROW 52000,N'El modulo historico de compras admite CRC o USD.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.Productos p JOIN dbo.ProductosBase b ON b.IdProductoBase=p.IdProductoBase LEFT JOIN dbo.Marcas m ON m.IdMarca=p.IdMarca
 JOIN dbo.PresentacionesProducto pp ON pp.IdProducto=p.IdProducto JOIN dbo.UnidadesMedida u ON u.IdUnidadMedida=pp.IdUnidadMedida
 WHERE p.IdProducto=@IdProducto AND pp.IdPresentacionProducto=@IdPresentacionProducto AND p.Activo=1 AND b.Activo=1 AND (p.IdMarca IS NULL OR m.Activo=1) AND pp.Activo=1 AND u.Activo=1)
 OR NOT EXISTS(SELECT 1 FROM dbo.Proveedores WHERE IdProveedor=@IdProveedor AND Activo=1) THROW 52000,N'Catalogos inactivos o producto y presentacion incompatibles.',1;
 DECLARE @Precio decimal(18,6)=TRY_CONVERT(decimal(18,6),@PrecioTotal/@CantidadComprada);
 IF @Precio IS NULL OR @Precio<=0 THROW 52000,N'Precio por empaque fuera de rango.',1;
 IF @IdCompraCabecera IS NULL
 BEGIN
   INSERT dbo.ComprasCabecera(IdProveedor,FechaCompra,Moneda,Observaciones)
   VALUES(@IdProveedor,@FechaCompra,@Moneda,NULLIF(TRIM(@Observaciones),N''));
   SET @IdCompraCabecera=CONVERT(bigint,SCOPE_IDENTITY());
   SET @NumeroLinea=1;
 END;
 IF @NumeroLinea IS NULL OR @NumeroLinea<1 OR NOT EXISTS
 (SELECT 1 FROM dbo.ComprasCabecera WITH(UPDLOCK,HOLDLOCK) WHERE IdCompraCabecera=@IdCompraCabecera
 AND IdProveedor=@IdProveedor AND FechaCompra=@FechaCompra AND Moneda=@Moneda)
 THROW 52000,N'El renglón no corresponde a la cabecera de la compra.',1;
 INSERT dbo.Compras(IdCompraCabecera,NumeroLinea,IdProducto,IdProveedor,IdPresentacionProducto,FechaCompra,CantidadComprada,PrecioTotal,Moneda,PrecioUnitarioCalculado,Observaciones)
 VALUES(@IdCompraCabecera,@NumeroLinea,@IdProducto,@IdProveedor,@IdPresentacionProducto,@FechaCompra,@CantidadComprada,@PrecioTotal,@Moneda,@Precio,NULLIF(LTRIM(RTRIM(@Observaciones)),N''));
 DECLARE @Id bigint=CONVERT(bigint,SCOPE_IDENTITY());
 /* Cache de compatibilidad; todas las lecturas usan la vista recalculada. */
 UPDATE c SET PrecioUnitarioCalculado=v.PrecioUnitarioCalculado,IdCompraAnterior=v.IdCompraAnterior,PrecioUnitarioAnterior=v.PrecioUnitarioAnterior,
 DiferenciaPrecio=v.DiferenciaPrecio,PorcentajeCambioPrecio=v.PorcentajeCambioPrecio,TendenciaPrecio=v.TendenciaPrecio
 FROM dbo.Compras c JOIN dbo.vw_ComprasAnalisis v ON v.IdCompra=c.IdCompra
 WHERE c.IdProducto=@IdProducto AND c.IdPresentacionProducto=@IdPresentacionProducto AND c.Moneda=@Moneda;
 IF @DistribucionPresupuestoJson IS NOT NULL
 EXEC dbo.usp_Presupuesto_ImputarCompra @Id,@DistribucionPresupuestoJson,@IdOperacionPresupuesto,@MotivoPresupuesto,@MotivoExcesoPresupuesto;
 IF @TranInicial=0 COMMIT;
 SET @IdCompraInsertada=@Id;
 IF @DevolverResultado=1 SELECT @Id AS IdCompraInsertada;
 END TRY BEGIN CATCH
 IF XACT_STATE()<>0 AND @TranInicial=0 ROLLBACK; ELSE IF XACT_STATE()=1 ROLLBACK TRANSACTION CompraReal;
 THROW;
 END CATCH;
END;

CREATE   PROCEDURE dbo.SP_Compra_Listar @Moneda nvarchar(10)=NULL,@Pagina int=1,@TamanoPagina int=50 AS
BEGIN
 SET NOCOUNT ON;
 IF @Pagina IS NULL OR @Pagina<1 OR @TamanoPagina IS NULL OR @TamanoPagina NOT BETWEEN 1 AND 200 THROW 52000,N'Paginacion invalida.',1;
 SELECT *,COUNT_BIG(*) OVER() AS TotalRegistros FROM dbo.vw_ComprasAnalisis WHERE @Moneda IS NULL OR Moneda=@Moneda
 ORDER BY FechaCompra DESC,IdCompra DESC OFFSET CONVERT(bigint,@Pagina-1)*@TamanoPagina ROWS FETCH NEXT @TamanoPagina ROWS ONLY;
END;

CREATE   PROCEDURE dbo.SP_Compra_ObtenerPorId @IdCompra bigint AS
BEGIN
 SET NOCOUNT ON;
 IF NOT EXISTS(SELECT 1 FROM dbo.Compras WHERE IdCompra=@IdCompra) THROW 52004,N'Compra no existe.',1;
 SELECT * FROM dbo.vw_ComprasAnalisis WHERE IdCompra=@IdCompra;
END;

CREATE   PROCEDURE dbo.SP_Compra_UltimoPrecio @IdProducto int,@IdPresentacionProducto int,@Moneda nvarchar(10) AS
BEGIN
 SET NOCOUNT ON;
 IF @Moneda IS NULL OR @Moneda NOT IN(N'CRC',N'USD') THROW 52000,N'Indique una moneda CRC o USD para comparar compras.',1; SELECT TOP(1) * FROM dbo.vw_ComprasAnalisis WHERE IdProducto=@IdProducto AND IdPresentacionProducto=@IdPresentacionProducto AND Moneda=@Moneda ORDER BY FechaCompra DESC,IdCompra DESC;
END;

CREATE   PROCEDURE dbo.SP_CompraAutomatica_BuscarEquivalencia
 @CodigoProveedor nvarchar(100)=NULL,@DescripcionProveedor nvarchar(300),@IdProveedor int
AS
BEGIN
 SET NOCOUNT ON;
 IF NOT EXISTS(SELECT 1 FROM dbo.Proveedores WHERE IdProveedor=@IdProveedor AND Activo=1)
 THROW 52000,N'Indique un proveedor activo para buscar sus equivalencias.',1;
 DECLARE @Codigo nvarchar(100)=NULLIF(UPPER(LTRIM(RTRIM(@CodigoProveedor))),N''),
 @Descripcion nvarchar(300)=NULLIF(UPPER(LTRIM(RTRIM(@DescripcionProveedor))),N'');
 DECLARE @C table(IdProducto int,IdPresentacionProducto int,NombreProducto nvarchar(150),NombrePresentacion nvarchar(150),CodigoNormalizado nvarchar(100),DescripcionNormalizada nvarchar(300));
 INSERT @C SELECT e.IdProducto,e.IdPresentacionProducto,p.Nombre,COALESCE(pp.Descripcion,N''),e.CodigoNormalizado,UPPER(LTRIM(RTRIM(e.DescripcionProveedor)))
 FROM dbo.CompraAutomaticaEquivalencias e JOIN dbo.Productos p ON p.IdProducto=e.IdProducto AND p.Activo=1
 JOIN dbo.ProductosBase b ON b.IdProductoBase=p.IdProductoBase AND b.Activo=1 LEFT JOIN dbo.Marcas m ON m.IdMarca=p.IdMarca
 LEFT JOIN dbo.PresentacionesProducto pp ON pp.IdPresentacionProducto=e.IdPresentacionProducto LEFT JOIN dbo.UnidadesMedida u ON u.IdUnidadMedida=pp.IdUnidadMedida
 WHERE e.IdProveedor=@IdProveedor AND e.Activo=1 AND (p.IdMarca IS NULL OR m.Activo=1)
 AND (e.IdPresentacionProducto IS NULL OR (pp.Activo=1 AND u.Activo=1));
 IF @Codigo IS NOT NULL AND EXISTS(SELECT 1 FROM @C WHERE CodigoNormalizado=@Codigo)
 BEGIN
  SELECT IdProducto,IdPresentacionProducto,NombreProducto,NombrePresentacion FROM @C WHERE CodigoNormalizado=@Codigo;
  RETURN;
 END;
 IF (SELECT COUNT(*) FROM @C WHERE DescripcionNormalizada=@Descripcion)>1
 THROW 52009,N'Hay varias equivalencias del mismo proveedor; requiere seleccion manual.',1;
 SELECT IdProducto,IdPresentacionProducto,NombreProducto,NombrePresentacion FROM @C WHERE DescripcionNormalizada=@Descripcion;
END;

CREATE   PROCEDURE dbo.SP_CompraAutomatica_BuscarPresentacion
 @IdProducto int,@Cantidad decimal(18,6),@IdUnidadMedida int
AS
BEGIN
 SET NOCOUNT ON;
 IF @Cantidad IS NULL OR @Cantidad<=0 THROW 52000,N'La cantidad de contenido debe ser explicita y positiva.',1;
 DECLARE @Factor decimal(18,6),@Tipo nvarchar(20);
 SELECT @Factor=FactorConversion,@Tipo=TipoBase FROM dbo.UnidadesMedida WHERE IdUnidadMedida=@IdUnidadMedida AND Activo=1;
 IF @Factor IS NULL THROW 52000,N'Unidad inexistente o inactiva. No se infiere desde texto ambiguo.',1;
 DECLARE @Normalizada decimal(18,6)=TRY_CONVERT(decimal(18,6),@Cantidad*@Factor);
 IF @Normalizada IS NULL OR @Normalizada<=0 THROW 52000,N'Contenido normalizado fuera de rango.',1;
 IF (SELECT COUNT(*) FROM dbo.PresentacionesProducto pp JOIN dbo.UnidadesMedida u ON u.IdUnidadMedida=pp.IdUnidadMedida
 WHERE pp.IdProducto=@IdProducto AND pp.Activo=1 AND u.Activo=1 AND u.TipoBase=@Tipo AND pp.CantidadNormalizada=@Normalizada)>1
 THROW 52009,N'Hay varias presentaciones con ese contenido; requiere seleccion manual.',1;
 SELECT pp.IdPresentacionProducto,pp.Descripcion AS NombrePresentacion,pp.Cantidad,pp.IdUnidadMedida,u.Codigo,u.TipoBase,pp.CantidadNormalizada
 FROM dbo.PresentacionesProducto pp JOIN dbo.Productos p ON p.IdProducto=pp.IdProducto AND p.Activo=1
 JOIN dbo.UnidadesMedida u ON u.IdUnidadMedida=pp.IdUnidadMedida AND u.Activo=1
 WHERE pp.IdProducto=@IdProducto AND pp.Activo=1 AND u.TipoBase=@Tipo AND pp.CantidadNormalizada=@Normalizada;
END;

CREATE   PROCEDURE dbo.SP_CompraAutomatica_BuscarProducto @Descripcion nvarchar(500) AS
BEGIN
 SET NOCOUNT ON;
 DECLARE @C table(IdProducto int,CodigoInterno nvarchar(40),NombreProducto nvarchar(150),IdProductoBase int,IdMarca int,Marca nvarchar(150),FormulaDeclarada nvarchar(100),CoincidenciaExacta bit,CantidadCandidatos int);
 INSERT @C EXEC dbo.usp_Producto_BuscarCandidatos @Descripcion;
 IF (SELECT COUNT(*) FROM @C)>1 THROW 52009,N'Hay varios productos candidatos; requiere seleccion manual.',1;
 SELECT IdProducto,NombreProducto,IdProductoBase,IdMarca,Marca,CoincidenciaExacta,CantidadCandidatos FROM @C;
END;

CREATE   PROCEDURE dbo.SP_CompraAutomatica_BuscarProveedor
 @NombreNegocio nvarchar(200)=NULL,@RazonSocial nvarchar(200)=NULL,
 @IdentificacionFiscal nvarchar(50)=NULL,@PaisIdentificacion char(2)=NULL,@TipoIdentificacion nvarchar(30)=NULL
AS
BEGIN
 SET NOCOUNT ON;
 DECLARE @A nvarchar(1000)=dbo.ufn_NormalizarTextoCatalogo(@NombreNegocio),@B nvarchar(1000)=dbo.ufn_NormalizarTextoCatalogo(@RazonSocial);
 DECLARE @C table(IdProveedor int,NombreProveedor nvarchar(150));
 IF NULLIF(LTRIM(RTRIM(@IdentificacionFiscal)),N'') IS NOT NULL
 BEGIN
  IF @PaisIdentificacion IS NULL OR @TipoIdentificacion IS NULL THROW 52000,N'Indique pais y tipo para buscar por identificacion fiscal.',1;
  INSERT @C SELECT IdProveedor,Nombre FROM dbo.Proveedores WHERE Activo=1 AND IdentificacionFiscal=@IdentificacionFiscal AND PaisIdentificacion=@PaisIdentificacion AND TipoIdentificacion=@TipoIdentificacion;
 END ELSE BEGIN
  IF @A=N'' AND @B=N'' THROW 52000,N'El proveedor requiere identidad o nombre del emisor.',1;
  INSERT @C SELECT IdProveedor,Nombre FROM dbo.Proveedores WHERE Activo=1
  AND ((@A<>N'' AND dbo.ufn_NormalizarTextoCatalogo(Nombre)=@A) OR (@B<>N'' AND dbo.ufn_NormalizarTextoCatalogo(Nombre)=@B));
 END;
 IF (SELECT COUNT(*) FROM @C)>1 THROW 52009,N'El nombre corresponde a varios proveedores; requiere seleccion manual.',1;
 SELECT * FROM @C;
END;

CREATE   PROCEDURE dbo.SP_CompraAutomatica_InsertarCompraDesdeProforma @IdProducto int,@IdProveedor int,@IdPresentacionProducto int,@FechaCompra date,@CantidadComprada decimal(18,4),@PrecioTotal decimal(18,4),@Moneda nvarchar(10),@Observaciones nvarchar(500)=NULL AS
BEGIN
 SET NOCOUNT ON;
 THROW 52010,N'Una cotizacion recibida no es una compra. Use usp_Proforma_GuardarBorrador y valide la respuesta; registre una compra real por separado.',1;
END;

CREATE   PROCEDURE dbo.SP_CompraAutomatica_InsertarEquivalencia
 @IdProveedor int,@CodigoProveedor nvarchar(100)=NULL,@DescripcionProveedor nvarchar(300),@IdProducto int,@IdPresentacionProducto int=NULL
AS
BEGIN
 SET NOCOUNT ON;
 IF NOT EXISTS(SELECT 1 FROM dbo.Proveedores WHERE IdProveedor=@IdProveedor AND Activo=1)
 OR NOT EXISTS(SELECT 1 FROM dbo.Productos WHERE IdProducto=@IdProducto AND Activo=1)
 THROW 52000,N'Proveedor o producto inexistente/inactivo.',1;
 IF @IdPresentacionProducto IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.PresentacionesProducto WHERE IdPresentacionProducto=@IdPresentacionProducto AND IdProducto=@IdProducto AND Activo=1)
 THROW 52000,N'La presentacion debe estar activa y pertenecer al producto.',1;
 IF NULLIF(LTRIM(RTRIM(@DescripcionProveedor)),N'') IS NULL THROW 52000,N'Descripcion de proveedor obligatoria.',1;
 INSERT dbo.CompraAutomaticaEquivalencias(IdProveedor,CodigoProveedor,DescripcionProveedor,IdProducto,IdPresentacionProducto)
 VALUES(@IdProveedor,NULLIF(LTRIM(RTRIM(@CodigoProveedor)),N''),LTRIM(RTRIM(@DescripcionProveedor)),@IdProducto,@IdPresentacionProducto);
 SELECT CONVERT(int,SCOPE_IDENTITY()) AS IdEquivalencia;
END;

CREATE   PROCEDURE dbo.SP_PresentacionesProducto_Actualizar
 @IdPresentacionProducto int,@IdProducto int,@Descripcion nvarchar(150),@Cantidad decimal(18,4),@IdUnidadMedida int,@CantidadNormalizada decimal(18,6)=NULL
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 DECLARE @TranInicial int=@@TRANCOUNT;
 IF @TranInicial=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION OperacionCatalogo;
 BEGIN TRY
IF NULLIF(LTRIM(RTRIM(@Descripcion)),N'') IS NULL THROW 52000,N'Descripcion es obligatorio.',1;
 IF @Cantidad IS NULL OR @Cantidad<=0 THROW 52000,N'Contenido por empaque debe ser positivo.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.Productos WHERE IdProducto=@IdProducto AND Activo=1) THROW 52000,N'Producto inexistente o inactivo.',1;
 DECLARE @Factor decimal(18,6)=(SELECT FactorConversion FROM dbo.UnidadesMedida WHERE IdUnidadMedida=@IdUnidadMedida AND Activo=1);
 IF @Factor IS NULL THROW 52000,N'Unidad inexistente o inactiva.',1;
 DECLARE @Calculada decimal(18,6)=TRY_CONVERT(decimal(18,6),@Cantidad*@Factor);
 IF @Calculada IS NULL OR @Calculada<=0 THROW 52000,N'Contenido normalizado fuera de rango.',1;
 IF @CantidadNormalizada IS NOT NULL AND @CantidadNormalizada<>@Calculada THROW 52000,N'Cantidad normalizada incoherente con el factor.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.PresentacionesProducto WITH(UPDLOCK,HOLDLOCK) WHERE IdPresentacionProducto=@IdPresentacionProducto) THROW 52004,N'Presentacion no existe.',1; UPDATE dbo.PresentacionesProducto SET IdProducto=@IdProducto,Descripcion=LTRIM(RTRIM(@Descripcion)),Cantidad=@Cantidad,IdUnidadMedida=@IdUnidadMedida,CantidadNormalizada=@Calculada,FechaModificacion=SYSUTCDATETIME() WHERE IdPresentacionProducto=@IdPresentacionProducto; SELECT @IdPresentacionProducto AS IdPresentacionProducto;
  IF @TranInicial=0 COMMIT;
 END TRY BEGIN CATCH
  IF XACT_STATE()<>0 AND @TranInicial=0 ROLLBACK;
  ELSE IF XACT_STATE()=1 ROLLBACK TRANSACTION OperacionCatalogo;
  THROW;
 END CATCH;
END;

CREATE   PROCEDURE dbo.SP_PresentacionesProducto_Desactivar
 @IdPresentacionProducto int
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 DECLARE @TranInicial int=@@TRANCOUNT;
 IF @TranInicial=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION OperacionCatalogo;
 BEGIN TRY
IF NOT EXISTS(SELECT 1 FROM dbo.PresentacionesProducto WITH(UPDLOCK,HOLDLOCK) WHERE IdPresentacionProducto=@IdPresentacionProducto) THROW 52004,N'Presentacion no existe.',1; UPDATE dbo.PresentacionesProducto SET Activo=0,FechaModificacion=SYSUTCDATETIME() WHERE IdPresentacionProducto=@IdPresentacionProducto; SELECT 1 AS FilasAfectadas;
  IF @TranInicial=0 COMMIT;
 END TRY BEGIN CATCH
  IF XACT_STATE()<>0 AND @TranInicial=0 ROLLBACK;
  ELSE IF XACT_STATE()=1 ROLLBACK TRANSACTION OperacionCatalogo;
  THROW;
 END CATCH;
END;

CREATE   PROCEDURE dbo.SP_PresentacionesProducto_Insertar
 @IdProducto int,@Descripcion nvarchar(150),@Cantidad decimal(18,4),@IdUnidadMedida int,@CantidadNormalizada decimal(18,6)=NULL
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 DECLARE @TranInicial int=@@TRANCOUNT;
 IF @TranInicial=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION OperacionCatalogo;
 BEGIN TRY
IF NULLIF(LTRIM(RTRIM(@Descripcion)),N'') IS NULL THROW 52000,N'Descripcion es obligatorio.',1;
 IF @Cantidad IS NULL OR @Cantidad<=0 THROW 52000,N'Contenido por empaque debe ser positivo.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.Productos WHERE IdProducto=@IdProducto AND Activo=1) THROW 52000,N'Producto inexistente o inactivo.',1;
 DECLARE @Factor decimal(18,6)=(SELECT FactorConversion FROM dbo.UnidadesMedida WHERE IdUnidadMedida=@IdUnidadMedida AND Activo=1);
 IF @Factor IS NULL THROW 52000,N'Unidad inexistente o inactiva.',1;
 DECLARE @Calculada decimal(18,6)=TRY_CONVERT(decimal(18,6),@Cantidad*@Factor);
