IF NOT EXISTS(SELECT 1 FROM dbo.Marcas WHERE IdMarca=@IdMarca) THROW 52004,N'Marca no existe.',1;
SELECT IdMarca,Nombre,Activo,FechaCreacion,FechaModificacion FROM dbo.Marcas WHERE IdMarca=@IdMarca;
END;

CREATE PROCEDURE dbo.usp_Presupuesto_Consultar @IdPresupuesto bigint
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;
    DECLARE @TranInicial int = @@TRANCOUNT;
    IF @TranInicial = 0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION Presupuesto;
    BEGIN TRY
        EXEC dbo.usp_Presupuesto_Bloquear 'Shared';
        IF NOT EXISTS (SELECT 1 FROM dbo.Presupuestos WHERE IdPresupuesto = @IdPresupuesto)
            THROW 52004, N'El presupuesto no existe.', 1;
        SELECT p.IdPresupuesto, p.Nombre, p.IdFinca, f.Nombre AS Finca, p.FechaInicio, p.FechaFin, p.Moneda, p.Estado,
            c.FechaRegistro AS FechaCreacion, a.FechaRegistro AS FechaAprobacion,
            z.FechaRegistro AS FechaCierre, z.Motivo AS MotivoCierre,
            COALESCE(p.IdOperacionEdicion,p.IdOperacionCreacion) AS Version
        FROM dbo.Presupuestos AS p LEFT JOIN dbo.Fincas AS f ON f.IdFinca = p.IdFinca
        JOIN dbo.OperacionesPresupuesto AS c ON c.IdOperacion = p.IdOperacionCreacion
        LEFT JOIN dbo.OperacionesPresupuesto AS a ON a.IdOperacion = p.IdOperacionAprobacion
        LEFT JOIN dbo.OperacionesPresupuesto AS z ON z.IdOperacion = p.IdOperacionCierre
        WHERE p.IdPresupuesto = @IdPresupuesto;

        SELECT s.IdPartidaPresupuesto, s.IdRubroPresupuesto, r.Nombre AS Rubro, s.MontoInicial, s.Aprobado,
            s.Comprometido, s.Ejecutado, s.Disponible
        FROM dbo.vw_SaldosPresupuesto AS s JOIN dbo.RubrosPresupuesto AS r ON r.IdRubroPresupuesto = s.IdRubroPresupuesto
        WHERE s.IdPresupuesto = @IdPresupuesto ORDER BY r.Nombre, s.IdPartidaPresupuesto;

        SELECT m.IdMovimientoPresupuesto, m.IdOperacion, m.IdPartidaPresupuesto, m.Tipo, m.CambioAprobado,
            m.CambioComprometido, m.CambioEjecutado, m.IdCompra, m.IdCompromisoDetalle, m.IdMovimientoRevertido,
            m.MotivoExceso, o.Motivo, o.FechaRegistro, o.UsuarioSql
        FROM dbo.MovimientosPresupuesto AS m JOIN dbo.PartidasPresupuesto AS p ON p.IdPartidaPresupuesto = m.IdPartidaPresupuesto
        JOIN dbo.OperacionesPresupuesto AS o ON o.IdOperacion = m.IdOperacion
        WHERE p.IdPresupuesto = @IdPresupuesto ORDER BY m.IdMovimientoPresupuesto DESC;

        SELECT s.IdCompromisoCompra, s.IdCompromisoDetalle, s.IdPartidaPresupuesto, s.IdProformaProveedorDetalle,
            c.FechaCompromiso, c.Estado, s.MontoReservado, s.Pendiente, s.Ejecutado, o.Motivo AS MotivoCierre
        FROM dbo.vw_SaldosCompromisoCompra AS s JOIN dbo.CompromisosCompra AS c ON c.IdCompromisoCompra = s.IdCompromisoCompra
        JOIN dbo.PartidasPresupuesto AS p ON p.IdPartidaPresupuesto = s.IdPartidaPresupuesto
        LEFT JOIN dbo.OperacionesPresupuesto AS o ON o.IdOperacion = c.IdOperacionCierre
        WHERE p.IdPresupuesto = @IdPresupuesto ORDER BY s.IdCompromisoCompra DESC, s.IdCompromisoDetalle;
        IF @TranInicial = 0 COMMIT;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0 AND @TranInicial = 0 ROLLBACK;
        ELSE IF XACT_STATE() = 1 ROLLBACK TRANSACTION Presupuesto;
        THROW;
    END CATCH;
END;

CREATE PROCEDURE dbo.usp_Presupuesto_EditarBorrador
 @IdPresupuesto bigint,@Version uniqueidentifier,@Nombre nvarchar(150),@FechaInicio date,@FechaFin date,
 @Moneda nvarchar(10),@PartidasJson nvarchar(max),@IdOperacion uniqueidentifier,@IdFinca int=NULL
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 DECLARE @TranInicial int=@@TRANCOUNT;
 IF @TranInicial=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION EditarPresupuesto;
 BEGIN TRY
 EXEC dbo.usp_Presupuesto_Bloquear;
 IF NOT EXISTS(SELECT 1 FROM dbo.Presupuestos WHERE IdPresupuesto=@IdPresupuesto)
   THROW 52004,N'El presupuesto no existe.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.Presupuestos WHERE IdPresupuesto=@IdPresupuesto AND Estado='Borrador')
   THROW 52010,N'Solo se pueden editar los datos iniciales de un presupuesto en borrador.',1;
 IF @Version IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.Presupuestos WHERE IdPresupuesto=@IdPresupuesto
     AND COALESCE(IdOperacionEdicion,IdOperacionCreacion)=@Version)
   THROW 52009,N'El borrador cambió. Recargue el presupuesto antes de guardar.',1;
 IF @IdOperacion IS NULL OR @IdOperacion='00000000-0000-0000-0000-000000000000'
   THROW 52000,N'Indique un identificador de operación válido.',1;
 SET @Moneda=UPPER(TRIM(@Moneda));
 IF NULLIF(TRIM(@Nombre),N'') IS NULL OR @FechaInicio IS NULL OR @FechaFin IS NULL OR @FechaFin<@FechaInicio
   OR @Moneda IS NULL OR @Moneda NOT IN(N'CRC',N'USD')
   THROW 52000,N'Indique nombre, período y moneda CRC o USD.',1;
 EXEC dbo.usp_Presupuesto_ValidarLineas @PartidasJson,N'idRubroPresupuesto';
 DECLARE @Partidas table(IdRubro int PRIMARY KEY,Monto decimal(18,4));
 IF EXISTS(SELECT IdRubro FROM OPENJSON(@PartidasJson) WITH(IdRubro bigint '$.idRubroPresupuesto') GROUP BY IdRubro HAVING COUNT(*)>1)
   THROW 52009,N'El rubro se repite en el presupuesto.',1;
 IF EXISTS(SELECT 1 FROM OPENJSON(@PartidasJson) WITH(IdRubro bigint '$.idRubroPresupuesto') WHERE IdRubro>2147483647)
   THROW 52000,N'El identificador de rubro está fuera del rango permitido.',1;
 INSERT @Partidas SELECT IdRubro,Monto FROM OPENJSON(@PartidasJson)
   WITH(IdRubro int '$.idRubroPresupuesto',Monto decimal(18,4) '$.monto');
 IF @IdFinca IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.Fincas WITH(HOLDLOCK) WHERE IdFinca=@IdFinca AND Activa=1)
   THROW 52000,N'Seleccione una finca activa.',1;
 IF EXISTS(SELECT 1 FROM @Partidas p LEFT JOIN dbo.RubrosPresupuesto r WITH(HOLDLOCK)
   ON r.IdRubroPresupuesto=p.IdRubro AND r.Activo=1 WHERE r.IdRubroPresupuesto IS NULL)
   THROW 52000,N'Use rubros activos para todas las partidas.',1;
 IF EXISTS(SELECT 1 FROM dbo.PartidasPresupuesto p JOIN dbo.MovimientosPresupuesto m ON m.IdPartidaPresupuesto=p.IdPartidaPresupuesto
     WHERE p.IdPresupuesto=@IdPresupuesto)
   OR EXISTS(SELECT 1 FROM dbo.PartidasPresupuesto p JOIN dbo.CompromisosCompraDetalle c ON c.IdPartidaPresupuesto=p.IdPartidaPresupuesto
     WHERE p.IdPresupuesto=@IdPresupuesto)
   THROW 52010,N'El borrador contiene movimientos o compromisos y debe revisarse antes de modificarlo.',1;
 DECLARE @Motivo nvarchar(500)=CONCAT(N'Edición de borrador del presupuesto #',@IdPresupuesto,N'.');
 EXEC dbo.usp_Presupuesto_RegistrarOperacion @IdOperacion,'EditarBorrador',@Motivo;
 UPDATE p SET MontoInicial=n.Monto FROM dbo.PartidasPresupuesto p JOIN @Partidas n ON n.IdRubro=p.IdRubroPresupuesto
   WHERE p.IdPresupuesto=@IdPresupuesto;
 DELETE p FROM dbo.PartidasPresupuesto p WHERE p.IdPresupuesto=@IdPresupuesto
   AND NOT EXISTS(SELECT 1 FROM @Partidas n WHERE n.IdRubro=p.IdRubroPresupuesto);
 INSERT dbo.PartidasPresupuesto(IdPresupuesto,IdRubroPresupuesto,MontoInicial)
 SELECT @IdPresupuesto,n.IdRubro,n.Monto FROM @Partidas n WHERE NOT EXISTS
   (SELECT 1 FROM dbo.PartidasPresupuesto p WHERE p.IdPresupuesto=@IdPresupuesto AND p.IdRubroPresupuesto=n.IdRubro);
 UPDATE dbo.Presupuestos SET Nombre=TRIM(@Nombre),IdFinca=@IdFinca,FechaInicio=@FechaInicio,FechaFin=@FechaFin,
   Moneda=@Moneda,IdOperacionEdicion=@IdOperacion WHERE IdPresupuesto=@IdPresupuesto;
 IF @TranInicial=0 COMMIT;
 END TRY BEGIN CATCH
 IF XACT_STATE()<>0 AND @TranInicial=0 ROLLBACK;
 ELSE IF XACT_STATE()=1 ROLLBACK TRANSACTION EditarPresupuesto;
 THROW;
 END CATCH;
END;

CREATE PROCEDURE dbo.usp_Presupuesto_EstablecerMonto
 @IdPartidaPresupuesto bigint,@NuevoMonto decimal(18,4),@MontoAprobadoEsperado decimal(28,4),
 @IdOperacion uniqueidentifier,@Motivo nvarchar(500)
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 DECLARE @TranInicial int=@@TRANCOUNT;
 IF @TranInicial=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION MontoPresupuesto;
 BEGIN TRY
 EXEC dbo.usp_Presupuesto_Bloquear;
 IF @NuevoMonto IS NULL OR @NuevoMonto<0 OR @IdOperacion IS NULL OR @IdOperacion='00000000-0000-0000-0000-000000000000'
   THROW 52000,N'Indique un nuevo monto no negativo y una operación válida.',1;
 IF NOT EXISTS(SELECT 1 FROM dbo.PartidasPresupuesto WHERE IdPartidaPresupuesto=@IdPartidaPresupuesto)
   THROW 52004,N'La partida no existe.',1;
 DECLARE @Actual decimal(28,4);
 SELECT @Actual=s.Aprobado FROM dbo.vw_SaldosPresupuesto s JOIN dbo.Presupuestos p ON p.IdPresupuesto=s.IdPresupuesto
   WHERE s.IdPartidaPresupuesto=@IdPartidaPresupuesto AND p.Estado='Aprobado';
 IF @Actual IS NULL THROW 52010,N'Solo se puede cambiar el monto de una partida aprobada.',1;
 IF @MontoAprobadoEsperado IS NULL OR @Actual<>@MontoAprobadoEsperado
   THROW 52009,N'El monto aprobado cambió. Recargue el presupuesto y revise el nuevo ajuste.',1;
 DECLARE @Ajuste decimal(18,4)=TRY_CONVERT(decimal(18,4),@NuevoMonto-@Actual);
 IF @Ajuste IS NULL THROW 52000,N'La diferencia supera el rango de un ajuste individual.',1;
 IF @Ajuste=0 THROW 52000,N'El nuevo monto es igual al aprobado; no hay cambios que guardar.',1;
 EXEC dbo.usp_Presupuesto_AjustarPartida @IdPartidaPresupuesto,@Ajuste,@IdOperacion,@Motivo;
 IF @TranInicial=0 COMMIT;
 END TRY BEGIN CATCH
 IF XACT_STATE()<>0 AND @TranInicial=0 ROLLBACK;
 ELSE IF XACT_STATE()=1 ROLLBACK TRANSACTION MontoPresupuesto;
 THROW;
 END CATCH;
END;

CREATE   PROCEDURE dbo.usp_Producto_BuscarCandidatos
 @Descripcion nvarchar(500),@IdProductoBase int=NULL,@IdMarca int=NULL
AS
BEGIN
 SET NOCOUNT ON;
 DECLARE @Texto nvarchar(1000)=dbo.ufn_NormalizarTextoCatalogo(@Descripcion);
 IF NULLIF(@Texto,N'') IS NULL THROW 52000,N'Descripcion vacia; requiere seleccion manual.',1;
 SELECT p.IdProducto,p.CodigoInterno,p.Nombre AS NombreProducto,p.IdProductoBase,p.IdMarca,m.Nombre AS Marca,b.FormulaDeclarada,
 CONVERT(bit,CASE WHEN dbo.ufn_NormalizarTextoCatalogo(p.Nombre)=@Texto THEN 1 ELSE 0 END) AS CoincidenciaExacta,
 COUNT(*) OVER() AS CantidadCandidatos
 FROM dbo.Productos p JOIN dbo.ProductosBase b ON b.IdProductoBase=p.IdProductoBase LEFT JOIN dbo.Marcas m ON m.IdMarca=p.IdMarca
 WHERE p.Activo=1 AND b.Activo=1 AND (p.IdMarca IS NULL OR m.Activo=1)
 AND (@IdProductoBase IS NULL OR p.IdProductoBase=@IdProductoBase) AND (@IdMarca IS NULL OR p.IdMarca=@IdMarca)
 AND (p.CodigoInterno=@Descripcion OR CHARINDEX(N' '+dbo.ufn_NormalizarTextoCatalogo(p.Nombre)+N' ',N' '+@Texto+N' ')>0)
 ORDER BY CoincidenciaExacta DESC,p.IdProducto;
END;

CREATE   PROCEDURE dbo.usp_ProductoBase_Actualizar
 @IdProductoBase int,@Codigo nvarchar(40),@Nombre nvarchar(150),@FormulaDeclarada nvarchar(100)=NULL,@Descripcion nvarchar(500)=NULL,@ComparabilidadRevisada bit=0
AS
BEGIN
 SET NOCOUNT ON;
 SET XACT_ABORT ON;
 DECLARE @TranInicial int=@@TRANCOUNT;
 IF @TranInicial=0 BEGIN TRANSACTION; ELSE SAVE TRANSACTION OperacionCatalogo;
 BEGIN TRY
IF NULLIF(LTRIM(RTRIM(@Nombre)),N'') IS NULL THROW 52000,N'Nombre es obligatorio.',1;
IF NULLIF(LTRIM(RTRIM(@Codigo)),N'') IS NULL THROW 52000,N'Codigo es obligatorio.',1;
IF @ComparabilidadRevisada IS NULL THROW 52000,N'Indique si la agrupacion fue revisada.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.ProductosBase WITH(UPDLOCK,HOLDLOCK) WHERE IdProductoBase=@IdProductoBase) THROW 52004,N'ProductoBase no existe.',1;
UPDATE dbo.ProductosBase SET Codigo=LTRIM(RTRIM(@Codigo)),Nombre=LTRIM(RTRIM(@Nombre)),FormulaDeclarada=NULLIF(LTRIM(RTRIM(@FormulaDeclarada)),N''),Descripcion=NULLIF(LTRIM(RTRIM(@Descripcion)),N''),ComparabilidadRevisada=@ComparabilidadRevisada,FechaModificacion=SYSUTCDATETIME() WHERE IdProductoBase=@IdProductoBase;
SELECT @IdProductoBase AS IdProductoBase;
  IF @TranInicial=0 COMMIT;
 END TRY BEGIN CATCH
  IF XACT_STATE()<>0 AND @TranInicial=0 ROLLBACK;
  ELSE IF XACT_STATE()=1 ROLLBACK TRANSACTION OperacionCatalogo;
  THROW;
 END CATCH;
END;

